head.b:skin:
/*
-----------------------------------------------
ANTINNA MULTI-NICHE PLATFORM V4.0 (PRODUCTION)
-----------------------------------------------
*/
:root {
  --primary: #00f2ff;
  --primary-dark: #00c8d4;
  --bg-body: #ffffff;
  --bg-alt: #f8f9fa;
  --text-main: #1a1a1a;
  --text-muted: #666666;
  --border-color: #eeeeee;
  --card-shadow: 0 4px 20px rgba(0,0,0,0.05);
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

/* Dark Mode Support */
@media (prefers-color-scheme: dark) {
  :root {
    --bg-body: #0a0a0a;
    --bg-alt: #111111;
    --text-main: #f0f0f0;
    --text-muted: #999999;
    --border-color: #222222;
  }
}

body {
  background-color: var(--bg-body);
  color: var(--text-main);
  font-family: var(--font-sans);
  margin: 0; padding: 0;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--primary); text-decoration: none; transition: 0.2s; }
a:hover { color: var(--primary-dark); }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* --- NAVIGATION --- */
nav.navbar {
  background: var(--bg-body);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
  position: sticky; top: 0; z-index: 1000;
}
.nav-flex { display: flex; justify-content: space-between; align-items: center; }
.brand { font-weight: 700; font-size: 1.5rem; letter-spacing: -0.5px; }
.brand span { color: var(--primary); }
.nav-links { display: flex; gap: 2rem; list-style: none; margin: 0; padding: 0; }
.nav-links a { color: var(--text-main); font-weight: 500; font-size: 0.95rem; }

/* --- HERO SECTION --- */
.hero {
  padding: 100px 0;
  background: var(--bg-alt);
  border-bottom: 1px solid var(--border-color);
  text-align: center;
}
.hero h1 { font-size: 3.5rem; font-weight: 800; margin-bottom: 1rem; letter-spacing: -1.5px; line-height: 1.1; }
.hero p { color: var(--text-muted); font-size: 1.25rem; max-width: 700px; margin: 0 auto 2rem; }

/* --- SECTION TITLES --- */
.section-title { font-weight: 700; font-size: 1.75rem; margin-bottom: 2rem; display: flex; align-items: center; gap: 12px; }
.section-title::after { content: ''; flex: 1; height: 1px; background: var(--border-color); }

/* --- 1. SOCIAL MENTORSHIP SECTION --- */
.mentor-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 24px; margin-bottom: 60px; }
.mentor-card {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  text-align: center;
  transition: 0.2s;
}
.mentor-card:hover { border-color: var(--primary); box-shadow: var(--card-shadow); }
.mentor-avatar { width: 80px; height: 80px; border-radius: 50%; background: var(--bg-alt); margin: 0 auto 16px; object-fit: cover; }
.mentor-name { font-weight: 700; font-size: 1.1rem; margin-bottom: 4px; }
.mentor-niche { font-size: 0.8rem; font-weight: 600; color: var(--primary); text-transform: uppercase; margin-bottom: 16px; }

/* --- 2. DASHBOARD / HANDY SERVICES --- */
.dashboard-card {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  box-shadow: var(--card-shadow);
  margin-bottom: 60px;
  overflow-x: auto;
}
.service-table { width: 100%; border-collapse: collapse; min-width: 600px; }
.service-table th { text-align: left; padding: 12px; font-size: 0.8rem; text-transform: uppercase; color: var(--text-muted); border-bottom: 1px solid var(--border-color); }
.service-table td { padding: 16px 12px; border-bottom: 1px solid var(--border-color); font-size: 0.95rem; }

.status-pill {
  display: inline-flex; align-items: center; padding: 4px 12px; border-radius: 20px; font-size: 0.75rem; font-weight: 600;
}
.status-active { background: #e6fffa; color: #2c7a7b; }
.status-pending { background: #fffaf0; color: #9c4221; }

.progress-track { height: 6px; background: var(--bg-alt); border-radius: 3px; overflow: hidden; margin-top: 8px; width: 100px; }
.progress-fill { height: 100%; background: var(--primary); border-radius: 3px; }

/* --- 3. COMMERCE GRID --- */
.product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 32px; margin-bottom: 60px; }
.product-card {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}
.product-card:hover { transform: translateY(-4px); box-shadow: 0 12px 30px rgba(0,0,0,0.1); }
.product-img { width: 100%; height: 220px; object-fit: cover; background: var(--bg-alt); }
.product-info { padding: 20px; }
.product-cat { font-size: 0.75rem; font-weight: 700; color: var(--primary); text-transform: uppercase; margin-bottom: 8px; }
.product-name { font-weight: 700; font-size: 1.15rem; margin-bottom: 8px; color: var(--text-main); height: 2.8em; overflow: hidden; }
.product-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 16px; }
.price { font-weight: 700; font-size: 1.25rem; }

/* --- BUTTONS --- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 20px; border-radius: 8px; font-weight: 600; font-size: 0.9rem;
  cursor: pointer; transition: 0.2s; border: none; text-align: center;
}
.btn-primary { background: var(--primary); color: #000; }
.btn-primary:hover { background: var(--primary-dark); }
.btn-outline { background: transparent; border: 1px solid var(--border-color); color: var(--text-main); }
.btn-outline:hover { background: var(--bg-alt); }
.btn-sm { padding: 6px 12px; font-size: 0.8rem; }

/* --- BLOG FEED --- */
.blog-item { padding: 24px 0; border-bottom: 1px solid var(--border-color); }
.blog-item h3 { font-size: 1.5rem; margin-bottom: 0.5rem; }
.blog-meta { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 1rem; }

footer {
  background: var(--bg-alt);
  padding: 80px 0;
  border-top: 1px solid var(--border-color);
  margin-top: 80px;
  color: var(--text-muted);
  font-size: 0.9rem;
}

@media (max-width: 768px) {
  .hero h1 { font-size: 2.5rem; }
  .nav-links { display: none; }
  .mentor-grid { grid-template-columns: 1fr; }
}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//
